import requests
import sys

BASE_URL = "http://localhost:8000"
TIMEOUT = 30


def _extract_field(obj, candidates):
    for k in candidates:
        if k in obj:
            return obj[k], k
    return None, None


def test_get_catalog_products_returns_correct_product_data():
    try:
        resp = requests.get(f"{BASE_URL}/catalog/products", timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Request to /catalog/products failed: {e}")

    assert resp.status_code == 200, f"/catalog/products returned {resp.status_code}: {resp.text}"
    try:
        products = resp.json()
    except ValueError:
        raise AssertionError("/catalog/products did not return valid JSON")

    assert isinstance(products, list), f"/catalog/products should return a list, got {type(products)}"
    assert len(products) > 0, "/catalog/products returned an empty list; expected demo data"

    # Try to fetch inventory to cross-check stock levels (optional, but helpful)
    inventory_by_product = {}
    try:
        inv_resp = requests.get(f"{BASE_URL}/inventory", timeout=TIMEOUT)
        if inv_resp.status_code == 200:
            try:
                inventory = inv_resp.json()
                if isinstance(inventory, list):
                    for item in inventory:
                        # common inventory field names
                        pid, _ = _extract_field(item, ["product_id", "producto_id", "id", "producto"])
                        qty, _ = _extract_field(item, ["cantidad", "cantidad_actual", "cantidad_disponible", "quantity"])
                        try:
                            if pid is not None:
                                pid_int = int(pid)
                                if qty is not None:
                                    inventory_by_product[pid_int] = int(qty)
                        except Exception:
                            # skip if conversion fails
                            continue
            except ValueError:
                # ignore parsing errors for inventory
                pass
    except requests.RequestException:
        # inventory endpoint may be temporarily unreachable; continue with product-only checks
        pass

    # Define candidate field names
    id_keys = ["id", "product_id", "producto_id"]
    name_keys = ["nombre", "name", "titulo", "producto"]
    price_keys = ["precio_centavos", "price_centavos", "precio", "price"]
    reference_keys = [
        "precio_referencia_centavos",
        "precio_referencia",
        "precio_referencia_pesos",
        "referencia_precio_centavos",
        "referencia",
        "precio_anterior_centavos",
        "precio_antes_centavos",
    ]
    stock_label_keys = ["stock_estado", "stock_label", "disponible", "agotado", "cantidad", "stock"]

    # Validate several products (limit to first 50 to avoid huge loops)
    for idx, prod in enumerate(products[:50]):
        assert isinstance(prod, dict), f"Each product must be an object, item {idx} is {type(prod)}"

        pid, pid_key = _extract_field(prod, id_keys)
        assert pid is not None, f"Product at index {idx} missing id (tried {id_keys})"
        try:
            pid_int = int(pid)
        except Exception:
            raise AssertionError(f"Product id value is not an integer-convertible for product index {idx}: {pid}")

        name, name_key = _extract_field(prod, name_keys)
        assert name is not None and isinstance(name, str) and name.strip() != "", (
            f"Product {pid_int} missing a valid name (tried {name_keys})"
        )

        price, price_key = _extract_field(prod, price_keys)
        assert price is not None, f"Product {pid_int} missing a price field (tried {price_keys})"
        try:
            price_int = int(price)
        except Exception:
            raise AssertionError(f"Product {pid_int} price is not integer-convertible: {price}")
        assert price_int >= 0, f"Product {pid_int} has negative precio_centavos: {price_int}"

        # Reference price is optional but if present should be integer >= 0
        ref_price, ref_key = _extract_field(prod, reference_keys)
        if ref_price is not None:
            try:
                ref_int = int(ref_price)
            except Exception:
                raise AssertionError(f"Product {pid_int} reference price {ref_price} is not integer-convertible")
            assert ref_int >= 0, f"Product {pid_int} has negative reference price: {ref_int}"

        # Cross-check inventory if available
        if pid_int in inventory_by_product:
            inv_qty = inventory_by_product[pid_int]
            assert isinstance(inv_qty, int) and inv_qty >= 0, f"Inventory for product {pid_int} must be non-negative int"
            # If product exposes a cantidad or stock field, verify consistency
            prod_qty, prod_qty_key = _extract_field(prod, ["cantidad", "stock", "available", "disponible", "existencias"])
            if prod_qty is not None:
                try:
                    prod_qty_int = int(prod_qty)
                    assert prod_qty_int == inv_qty, (
                        f"Product {pid_int} reported cantidad {prod_qty_int} but inventory shows {inv_qty}"
                    )
                except Exception:
                    # If conversion fails, still report a meaningful error
                    raise AssertionError(f"Product {pid_int} cantidad field {prod_qty} is not integer-convertible")

        # If product contains explicit stock label, ensure it is a non-empty string
        stock_label, stock_label_key = _extract_field(prod, stock_label_keys)
        if stock_label is not None:
            # Accept both numeric quantities and descriptive labels
            if isinstance(stock_label, str):
                assert stock_label.strip() != "", f"Product {pid_int} has empty stock label"
            else:
                # if numeric, ensure non-negative
                try:
                    sval = int(stock_label)
                    assert sval >= 0, f"Product {pid_int} has negative stock label value {sval}"
                except Exception:
                    # allow other types but ensure not None
                    pass

    print("TC001: /catalog/products returned a valid products list with prices and (where available) consistent stock and reference pricing.")


if __name__ == "__main__":
    try:
        test_get_catalog_products_returns_correct_product_data()
    except AssertionError as e:
        print(f"TEST FAILED: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"UNEXPECTED ERROR: {e}")
        sys.exit(2)
    print("TEST PASSED")
    sys.exit(0)

import requests
import uuid
import sys
import time

BASE_URL = "http://localhost:8000"
TIMEOUT = 30

ADMIN_EMAIL = "admin.antojos@utb.edu.co"
ADMIN_PASSWORD = "Tienda-2026"


def login(email, password):
    url = f"{BASE_URL}/identity/login"
    resp = requests.post(url, json={"email": email, "password": password}, timeout=TIMEOUT)
    resp.raise_for_status()
    data = resp.json()
    token = data.get("access_token")
    assert token, "Login did not return access_token"
    return token


def create_product(token, tienda_slug, nombre, descripcion="created-by-test", precio_centavos=1000):
    url = f"{BASE_URL}/catalog/products"
    headers = {"Authorization": f"Bearer {token}"}
    payload = {
        "tienda": tienda_slug,
        "nombre": nombre,
        "descripcion": descripcion,
        "precio_centavos": precio_centavos,
        # include common fields if accepted by the API
        "presentacion": "Unidad"
    }
    resp = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
    if resp.status_code not in (200, 201):
        raise AssertionError(f"Create product failed: {resp.status_code} {resp.text}")
    return resp.json()


def set_inventory_quantity(token, product_id, cantidad):
    url = f"{BASE_URL}/inventory/{product_id}"
    headers = {"Authorization": f"Bearer {token}"}
    resp = requests.put(url, json={"cantidad": cantidad}, headers=headers, timeout=TIMEOUT)
    resp.raise_for_status()
    return resp.json()


def adjust_inventory(token, product_id, delta, motivo="conteo"):
    url = f"{BASE_URL}/inventory/{product_id}/adjust"
    headers = {"Authorization": f"Bearer {token}"}
    resp = requests.post(url, json={"delta": delta, "motivo": motivo}, headers=headers, timeout=TIMEOUT)
    resp.raise_for_status()
    return resp.json()


def get_inventory():
    url = f"{BASE_URL}/inventory"
    resp = requests.get(url, timeout=TIMEOUT)
    resp.raise_for_status()
    return resp.json()


def normalize_inventory_list(inventory_resp):
    # If response is already a list, return it. Otherwise try common envelopes.
    if isinstance(inventory_resp, list):
        return inventory_resp
    if isinstance(inventory_resp, dict):
        for key in ("items", "data", "results", "inventory", "inventario"):
            val = inventory_resp.get(key)
            if isinstance(val, list):
                return val
        # sometimes single object
        return [inventory_resp]
    # unknown type
    return []


def find_inventory_item(inventory_list, product_id=None, product_name=None):
    for item in inventory_list:
        # try various possible keys
        if product_id is not None:
            if str(item.get("product_id") or item.get("producto_id") or item.get("id") or item.get("inventory_id") or item.get("producto") and (isinstance(item.get("producto"), (str, int)) and str(item.get("producto")) == str(product_id))) == str(product_id):
                return item
            # some APIs embed product as nested object
            prod = item.get("producto") or item.get("product") or item.get("producto_info") or item.get("product_info")
            if isinstance(prod, dict) and str(prod.get("id") or prod.get("product_id") or prod.get("producto_id")) == str(product_id):
                return item
        if product_name is not None:
            # try name fields on the item
            name = item.get("nombre") or item.get("name") or item.get("titulo") or item.get("title")
            if name and name == product_name:
                return item
            prod = item.get("producto") or item.get("product")
            if isinstance(prod, dict):
                pname = prod.get("nombre") or prod.get("name") or prod.get("titulo") or prod.get("title")
                if pname and pname == product_name:
                    return item
            # sometimes product name lives under nested inventory object
            inv = item.get("inventario") or item.get("inventory")
            if isinstance(inv, dict):
                pname = inv.get("nombre") or inv.get("name")
                if pname and pname == product_name:
                    return item
    return None


def extract_cantidad_from_item(item):
    # Try top-level keys
    possible_keys = [
        "cantidad", "stock", "cantidad_actual", "cantidad_disponible", "disponible", "available",
        "qty", "quantity", "stock_actual", "cantidad_total", "existencias", "unidades"
    ]
    if not isinstance(item, dict):
        return None
    for k in possible_keys:
        if k in item and item.get(k) is not None:
            return item.get(k)
    # Try nested common containers
    for container_key in ("producto", "product", "inventario", "inventory", "item", "data"):
        nested = item.get(container_key)
        if isinstance(nested, dict):
            for k in possible_keys:
                if k in nested and nested.get(k) is not None:
                    return nested.get(k)
            # deeper: sometimes inventory is a list under the nested object
            if isinstance(nested.get("inventario") or nested.get("inventory"), dict):
                deeper = nested.get("inventario") or nested.get("inventory")
                for k in possible_keys:
                    if k in deeper and deeper.get(k) is not None:
                        return deeper.get(k)
    # Sometimes inventory entries are lists under item
    for list_key in ("inventarios", "inventario", "inventory", "stocks", "stock_items"):
        lst = item.get(list_key)
        if isinstance(lst, list) and len(lst) > 0:
            first = lst[0]
            if isinstance(first, dict):
                for k in possible_keys:
                    if k in first and first.get(k) is not None:
                        return first.get(k)
    return None


def delete_product(token, product_id):
    headers = {"Authorization": f"Bearer {token}"}
    # Try DELETE if available
    try:
        resp = requests.delete(f"{BASE_URL}/catalog/products/{product_id}", headers=headers, timeout=TIMEOUT)
        # treat 200/204/202 as success; if 405/404 may not be supported
        if resp.status_code in (200, 202, 204):
            return True
    except requests.RequestException:
        pass
    # fallback to PATCH to disable product (best-effort cleanup)
    try:
        resp = requests.patch(f"{BASE_URL}/catalog/products/{product_id}", json={"a_la_venta": False}, headers=headers, timeout=TIMEOUT)
        if resp.status_code in (200, 204):
            return True
    except requests.RequestException:
        pass
    return False


def test_verify_get_inventory_endpoint_returns_current_stock_levels():
    token = None
    product = None
    product_id = None
    unique_name = f"test-inventory-product-{uuid.uuid4()}"
    try:
        # Login as store admin (antojos)
        token = login(ADMIN_EMAIL, ADMIN_PASSWORD)

        # Create a new product in the antojos store so we can control its inventory
        created = create_product(token, "antojos", unique_name, descripcion="inventory-test", precio_centavos=1500)
        # The API may return the created product object or an envelope
        # Try to extract the product id
        if isinstance(created, dict):
            product_id = created.get("id") or created.get("product_id") or created.get("producto_id")
            product = created
        elif isinstance(created, list) and len(created) > 0:
            # unexpected list, pick first
            product = created[0]
            product_id = product.get("id") or product.get("product_id") or product.get("producto_id")

        assert product_id is not None, f"Could not determine created product id from response: {created}"

        # Set inventory to 5
        set_resp = set_inventory_quantity(token, product_id, 5)
        # Some APIs return the inventory object; verify cantidad at least in response if present
        if isinstance(set_resp, dict):
            cantidad = (set_resp.get("cantidad") or set_resp.get("cantidad_actual") or set_resp.get("stock") or
                        set_resp.get("cantidad_disponible") or set_resp.get("available"))
            if cantidad is not None:
                assert int(cantidad) == 5, f"Expected inventory cantidad 5, got {cantidad}"

        # GET /inventory and verify the product shows cantidad 5
        inventory = get_inventory()
        inventory_list = normalize_inventory_list(inventory)
        assert isinstance(inventory_list, list), "GET /inventory did not return a list or envelope with list"
        item = find_inventory_item(inventory_list, product_id=product_id, product_name=unique_name)
        assert item is not None, "Created product not found in GET /inventory"
        # Extract cantidad from item using robust extractor
        found_cantidad = extract_cantidad_from_item(item)
        assert found_cantidad is not None, f"Inventory item missing cantidad or equivalent; item: {item}"
        assert int(found_cantidad) == 5, f"Inventory cantidad mismatch: expected 5, got {found_cantidad}"

        # Now set low stock -> 1 and verify
        set_inventory_quantity(token, product_id, 1)
        inventory = get_inventory()
        inventory_list = normalize_inventory_list(inventory)
        item = find_inventory_item(inventory_list, product_id=product_id, product_name=unique_name)
        assert item is not None, "Product disappeared from inventory after setting low stock"
        found_cantidad = extract_cantidad_from_item(item)
        assert found_cantidad is not None, f"Inventory item missing cantidad after low-stock set; item: {item}"
        assert int(found_cantidad) == 1, f"Expected low stock cantidad 1, got {found_cantidad}"

        # Then adjust inventory by -1 to make it sold out (0)
        adjust_inventory(token, product_id, -1, motivo="conteo")
        inventory = get_inventory()
        inventory_list = normalize_inventory_list(inventory)
        item = find_inventory_item(inventory_list, product_id=product_id, product_name=unique_name)
        assert item is not None, "Product disappeared from inventory after adjusting to zero"
        found_cantidad = extract_cantidad_from_item(item)
        assert found_cantidad is not None, f"Inventory item missing cantidad after adjusting to zero; item: {item}"
        assert int(found_cantidad) == 0, f"Expected sold-out cantidad 0, got {found_cantidad}"

        # Finally set a moderate stock again (2) and verify
        set_inventory_quantity(token, product_id, 2)
        inventory = get_inventory()
        inventory_list = normalize_inventory_list(inventory)
        item = find_inventory_item(inventory_list, product_id=product_id, product_name=unique_name)
        assert item is not None, "Product missing from inventory after restocking to 2"
        found_cantidad = extract_cantidad_from_item(item)
        assert found_cantidad is not None, f"Inventory item missing cantidad after restock; item: {item}"
        assert int(found_cantidad) == 2, f"Expected cantidad 2 after restock, got {found_cantidad}"

        print("TC002 passed: GET /inventory returns up-to-date stock levels and handles low/sold-out states.")
    except Exception as e:
        print(f"TC002 failed: {e}")
        raise
    finally:
        # Cleanup: attempt to delete or deactivate the created product
        if token and product_id:
            ok = delete_product(token, product_id)
            if not ok:
                print(f"Cleanup warning: could not delete or deactivate product {product_id}", file=sys.stderr)


if __name__ == "__main__":
    test_verify_get_inventory_endpoint_returns_current_stock_levels()

import requests
import uuid
import sys
from requests.exceptions import RequestException, Timeout, HTTPError

BASE_URL = "http://localhost:8000"
TIMEOUT = 30  # seconds

def test_post_identity_register_creates_new_user_accounts():
    unique_suffix = uuid.uuid4().hex
    name = f"Test User {unique_suffix}"
    email = f"testuser+{unique_suffix}@example.com"
    password = "TestPass-2026!"  # satisfies typical complexity rules

    register_url = f"{BASE_URL}/identity/register"
    login_url = f"{BASE_URL}/identity/login"
    delete_me_url = f"{BASE_URL}/identity/me"

    headers = {"Content-Type": "application/json"}

    created_token = None
    created_user_info = None

    try:
        # 1) Register the new user (API expects 'nombre' instead of 'name')
        register_payload = {"nombre": name, "email": email, "password": password}
        try:
            r = requests.post(register_url, json=register_payload, headers=headers, timeout=TIMEOUT)
        except (RequestException, Timeout) as e:
            raise AssertionError(f"Registration request failed: {e}")

        # Accept 200 or 201 for successful creation
        assert r.status_code in (200, 201), f"Unexpected status code for register: {r.status_code}, body: {r.text}"

        # If response has JSON, try to validate returned fields
        try:
            reg_json = r.json()
            # If API returns created user object, validate email/name presence
            if isinstance(reg_json, dict):
                if "email" in reg_json:
                    assert reg_json.get("email") == email, "Registered email in response does not match"
                # Accept either 'nombre' or 'name' in response
                if "nombre" in reg_json:
                    assert reg_json.get("nombre") == name, "Registered nombre in response does not match"
                elif "name" in reg_json:
                    assert reg_json.get("name") == name, "Registered name in response does not match"
                created_user_info = reg_json
        except ValueError:
            # No JSON returned; proceed to login to confirm account was created
            reg_json = None

        # 2) Attempt to login with the new credentials to ensure the account works
        login_payload = {"email": email, "password": password}
        try:
            r2 = requests.post(login_url, json=login_payload, headers=headers, timeout=TIMEOUT)
        except (RequestException, Timeout) as e:
            raise AssertionError(f"Login request after register failed: {e}")

        assert r2.status_code == 200, f"Login failed after registration. Status: {r2.status_code}, body: {r2.text}"
        try:
            login_json = r2.json()
        except ValueError:
            raise AssertionError("Login response is not valid JSON")

        assert "access_token" in login_json and login_json["access_token"], "access_token missing or empty in login response"
        assert "expires_in" in login_json, "expires_in missing in login response"

        created_token = login_json["access_token"]

        # Optional: verify that /identity/me returns the new user's info when authenticated
        me_headers = {"Authorization": f"Bearer {created_token}"}
        try:
            r3 = requests.get(delete_me_url, headers=me_headers, timeout=TIMEOUT)
        except (RequestException, Timeout) as e:
            raise AssertionError(f"GET /identity/me failed: {e}")

        assert r3.status_code == 200, f"Authenticated GET /identity/me expected 200, got {r3.status_code}. Body: {r3.text}"
        try:
            me_json = r3.json()
            # Basic checks: email present and matches
            if isinstance(me_json, dict) and "email" in me_json:
                assert me_json.get("email") == email, "Identity 'me' email does not match registered email"
        except ValueError:
            raise AssertionError("GET /identity/me did not return valid JSON")

        print("Registration and login flow succeeded for", email)

    finally:
        # Cleanup: try to delete the created account using DELETE /identity/me if supported
        if created_token:
            try:
                del_headers = {"Authorization": f"Bearer {created_token}"}
                resp = requests.delete(delete_me_url, headers=del_headers, timeout=TIMEOUT)
                # Accept 200, 202, 204 as successful deletion; 404/405 may mean endpoint not supported — ignore but log
                if resp.status_code in (200, 202, 204):
                    print("Cleanup: deleted test user account.")
                else:
                    print(f"Cleanup: DELETE /identity/me returned status {resp.status_code}, body: {resp.text}")
            except Exception as e:
                print(f"Cleanup: failed to delete test user account: {e}")
        else:
            print("No authenticated token obtained; skipping delete cleanup.")

if __name__ == "__main__":
    try:
        test_post_identity_register_creates_new_user_accounts()
        print("TEST PASSED")
    except AssertionError as e:
        print("TEST FAILED:", e)
        sys.exit(1)
    except Exception as e:
        print("TEST ERROR:", e)
        sys.exit(2)

import requests
import uuid
import sys
import traceback

BASE_URL = "http://localhost:8000"
TIMEOUT = 30.0

BUYER_EMAIL = "ana@utb.edu.co"
BUYER_PASSWORD = "Comprador-2026"

STORE_ADMIN_EMAIL = "admin.almuerzo-01@utb.edu.co"
STORE_ADMIN_PASSWORD = "Tienda-2026"

PRODUCT_ID_FOR_ALMUERZO_01 = 52  # from PRD example list for Almuerzo 01

def login(email: str, password: str) -> str:
    url = f"{BASE_URL}/identity/login"
    resp = requests.post(url, json={"email": email, "password": password}, timeout=TIMEOUT)
    try:
        resp.raise_for_status()
    except Exception as e:
        raise AssertionError(f"Login failed for {email}: {resp.status_code} {resp.text}") from e
    data = resp.json()
    token = data.get("access_token")
    assert token, f"No access_token in login response for {email}: {data}"
    return token

def extract_order_id(order_obj):
    # Try common keys
    if not isinstance(order_obj, dict):
        raise AssertionError(f"Order object is not a dict: {order_obj}")
    for k in ("id", "order_id", "orderId", "pedido_id"):
        if k in order_obj:
            return order_obj[k]
    # fallback: maybe top-level contains nested order
    if "pedido" in order_obj and isinstance(order_obj["pedido"], dict):
        for k in ("id", "order_id", "orderId"):
            if k in order_obj["pedido"]:
                return order_obj["pedido"][k]
    raise AssertionError(f"Could not find order id in object: keys={list(order_obj.keys())}")

def get_estado_from_response(resp_json):
    if isinstance(resp_json, dict):
        for k in ("estado", "status", "estado_actual"):
            if k in resp_json:
                return resp_json[k]
        # maybe wrapped under 'pedido'
        if "pedido" in resp_json and isinstance(resp_json["pedido"], dict):
            for k in ("estado", "status"):
                if k in resp_json["pedido"]:
                    return resp_json["pedido"][k]
    return None

def test_verify_post_orders_orderid_estado_endpoint_advances_order_status():
    order_id = None
    created_order_obj = None
    buyer_token = None
    admin_token = None

    try:
        # 1) Login as buyer and create an order with a fresh Idempotency-Key
        buyer_token = login(BUYER_EMAIL, BUYER_PASSWORD)

        idempotency_key = str(uuid.uuid4())
        create_order_url = f"{BASE_URL}/orders"
        headers = {
            "Authorization": f"Bearer {buyer_token}",
            "Idempotency-Key": idempotency_key,
            "Content-Type": "application/json"
        }
        body = {
            "items": [
                {"product_id": PRODUCT_ID_FOR_ALMUERZO_01, "cantidad": 1}
            ]
            # "hora_recogida" optional
        }
        resp = requests.post(create_order_url, json=body, headers=headers, timeout=TIMEOUT)
        assert resp.status_code in (200,201), f"Unexpected status creating order: {resp.status_code} {resp.text}"
        resp_json = resp.json()

        # POST /orders returns a LIST of orders (one per store). Find the order for our product/store.
        if isinstance(resp_json, list):
            assert len(resp_json) >= 1, f"POST /orders returned empty list: {resp_json}"
            # pick first order object
            created_order_obj = resp_json[0]
        elif isinstance(resp_json, dict):
            # Some implementations might return a single object
            created_order_obj = resp_json
        else:
            raise AssertionError(f"Unexpected create order response type: {type(resp_json)}")

        order_id = extract_order_id(created_order_obj)
        assert order_id is not None, f"Could not determine order id from response: {created_order_obj}"

        # 2) Login as store admin for Almuerzo-01
        admin_token = login(STORE_ADMIN_EMAIL, STORE_ADMIN_PASSWORD)

        # 3) Advance through the lifecycle: pagado -> en_preparacion -> listo -> entregado
        estados = ["pagado", "en_preparacion", "listo", "entregado"]
        for estado in estados:
            url = f"{BASE_URL}/orders/{order_id}/estado"
            headers_admin = {
                "Authorization": f"Bearer {admin_token}",
                "Content-Type": "application/json"
            }
            payload = {"estado": estado}
            resp = requests.post(url, json=payload, headers=headers_admin, timeout=TIMEOUT)
            # Expect success (200). Some backends might return 204; accept 200 or 204.
            assert resp.status_code in (200, 204), f"Advancing to '{estado}' failed: {resp.status_code} {resp.text}"
            if resp.status_code == 200:
                resp_json = resp.json()
                new_estado = get_estado_from_response(resp_json)
                # If the API returns the updated order, validate estado field
                if new_estado is not None:
                    assert new_estado == estado, f"Expected estado '{estado}', got '{new_estado}' in response: {resp_json}"
            # If 204 no body is returned, we will verify by doing a GET /orders maybe, but PRD doesn't define GET /orders/{id} reliably.
            # As minimal validation, proceed to next state.

        # If we reached here, transitions succeeded
        print(f"Order {order_id} successfully advanced through states: {estados}")

    except Exception:
        traceback.print_exc()
        raise
    finally:
        # Cleanup: attempt to cancel the order as the store admin (best-effort). Do not fail test if cancellation not allowed.
        try:
            if order_id and admin_token:
                cancel_url = f"{BASE_URL}/orders/{order_id}/cancel"
                headers_admin = {
                    "Authorization": f"Bearer {admin_token}",
                    "Content-Type": "application/json"
                }
                cancel_resp = requests.post(cancel_url, headers=headers_admin, timeout=TIMEOUT)
                if cancel_resp.status_code in (200, 204):
                    print(f"Cleanup: order {order_id} cancelled by admin (status {cancel_resp.status_code}).")
                else:
                    # If cancellation fails (e.g., 400/403/404) print info but do not raise.
                    print(f"Cleanup: cancel attempt returned {cancel_resp.status_code}: {cancel_resp.text}")
        except Exception:
            print("Cleanup: exception while attempting to cancel order:")
            traceback.print_exc()


if __name__ == "__main__":
    test_verify_post_orders_orderid_estado_endpoint_advances_order_status()

import requests
import sys

BASE_URL = "http://localhost:8000"
TIMEOUT = 30


def test_general_admin_cannot_adjust_stock_and_gets_supervision_403():
    session = requests.Session()

    # 1) Login as general admin
    login_url = f"{BASE_URL}/identity/login"
    creds = {"email": "admin@utb.edu.co", "password": "Admin-Demo-2026"}
    try:
        r = session.post(login_url, json=creds, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise RuntimeError(f"Login request failed: {e}")
    assert r.status_code == 200, f"Login failed, expected 200 got {r.status_code}, body: {r.text}"
    try:
        token = r.json().get("access_token")
    except ValueError:
        raise AssertionError(f"Login response is not valid JSON: {r.text}")
    assert token, f"No access_token in login response: {r.text}"

    headers = {"Authorization": f"Bearer {token}"}

    inventory_id = 27
    inventory_url = f"{BASE_URL}/inventory/{inventory_id}"

    # Helper to get cantidad
    def get_cantidad():
        try:
            resp = session.get(inventory_url, headers=headers, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise RuntimeError(f"GET {inventory_url} failed: {e}")
        assert resp.status_code == 200, f"Expected 200 from GET {inventory_url}, got {resp.status_code}, body: {resp.text}"
        try:
            j = resp.json()
        except ValueError:
            raise AssertionError(f"GET {inventory_url} did not return JSON: {resp.text}")
        assert "cantidad" in j, f"'cantidad' not in GET {inventory_url} response: {j}"
        cantidad = j["cantidad"]
        assert isinstance(cantidad, int), f"'cantidad' should be int, got {type(cantidad)}: {cantidad}"
        return cantidad

    # 2) Read original cantidad
    original_cantidad = get_cantidad()

    # 3) Attempt POST adjust -> expect 403 with supervision detail
    adjust_url = f"{inventory_url}/adjust"
    adjust_payload = {"delta": 1, "motivo": "conteo"}
    try:
        resp_adjust = session.post(adjust_url, headers=headers, json=adjust_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise RuntimeError(f"POST {adjust_url} failed: {e}")
    assert resp_adjust.status_code == 403, f"Expected 403 from POST {adjust_url}, got {resp_adjust.status_code}, body: {resp_adjust.text}"
    # parse detail
    detail_text = None
    try:
        jd = resp_adjust.json()
        if isinstance(jd, dict):
            detail_text = jd.get("detail") or jd.get("message") or str(jd)
        else:
            detail_text = str(jd)
    except ValueError:
        detail_text = resp_adjust.text or ""
    assert detail_text is not None, f"No detail in 403 response: {resp_adjust.text}"
    expected_prefix = "El administrador general solo supervisa"
    assert detail_text.startswith(expected_prefix), f"403 detail should start with '{expected_prefix}', got: '{detail_text}'"

    # 4) GET again and verify cantidad unchanged
    cantidad_after_adjust = get_cantidad()
    assert cantidad_after_adjust == original_cantidad, f"cantidad changed after forbidden adjust: was {original_cantidad}, now {cantidad_after_adjust}"

    # 5) Attempt PUT set cantidad -> expect 403 with same supervision detail
    put_payload = {"cantidad": 5}
    try:
        resp_put = session.put(inventory_url, headers=headers, json=put_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise RuntimeError(f"PUT {inventory_url} failed: {e}")
    assert resp_put.status_code == 403, f"Expected 403 from PUT {inventory_url}, got {resp_put.status_code}, body: {resp_put.text}"
    # parse detail
    detail_text_put = None
    try:
        jp = resp_put.json()
        if isinstance(jp, dict):
            detail_text_put = jp.get("detail") or jp.get("message") or str(jp)
        else:
            detail_text_put = str(jp)
    except ValueError:
        detail_text_put = resp_put.text or ""
    assert detail_text_put is not None, f"No detail in 403 response for PUT: {resp_put.text}"
    assert detail_text_put.startswith(expected_prefix), f"PUT 403 detail should start with '{expected_prefix}', got: '{detail_text_put}'"

    # 6) Final GET to ensure cantidad unchanged
    final_cantidad = get_cantidad()
    assert final_cantidad == original_cantidad, f"cantidad changed after forbidden PUT: was {original_cantidad}, now {final_cantidad}"

    print("TC011 passed: General admin cannot adjust or set stock and receives supervision 403; cantidad unchanged.")


if __name__ == "__main__":
    try:
        test_general_admin_cannot_adjust_stock_and_gets_supervision_403()
    except AssertionError as ae:
        print("AssertionError:", ae)
        sys.exit(1)
    except Exception as e:
        print("Error:", e)
        sys.exit(2)
    sys.exit(0)

