def test_buyer_cannot_use_admin_endpoints():
    # Login as buyer
    try:
        resp = requests.post(
            f"{BASE_URL}/identity/login",
            json={"email": "ana@utb.edu.co", "password": "Comprador-2026"},
            timeout=TIMEOUT,
