    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}

    # 1) Buyer should get 403 when adjusting inventory for product 25
    try:
        r_inv = requests.post(
            f"{BASE_URL}/inventory/25/adjust",
            headers=headers,
            json={"delta": 1, "motivo": "conteo"},
            timeout=TIMEOUT,
        )
    except RequestException as e:
        raise AssertionError(f"Inventory adjust request failed: {e}") from e

    assert r_inv.status_code == 403, f"Expected 403 for inventory adjust, got {r_inv.status_code}: {r_inv.text}"

    # 2) Buyer should get 403 when creating a product
    unique_name = f"test-product-{uuid.uuid4()}"
    try:
        r_prod = requests.post(
            f"{BASE_URL}/catalog/products",
            headers=headers,
            json={
                "tienda": "punto-fit",
                "nombre": unique_name,
                "descripcion": "x",
                "precio_centavos": 100000,
            },
            timeout=TIMEOUT,
        )
    except RequestException as e:
        raise AssertionError(f"Create product request failed: {e}") from e

    assert r_prod.status_code == 403, f"Expected 403 for creating product, got {r_prod.status_code}: {r_prod.text}"

    # 3) Buyer should get 403 when listing orders for a store (admin endpoint)
    try:
        r_orders_list = requests.get(
            f"{BASE_URL}/orders",
            headers=headers,
            params={"tienda_id": 1},
            timeout=TIMEOUT,
        )
    except RequestException as e:
        raise AssertionError(f"Get orders by tienda_id request failed: {e}") from e

    assert r_orders_list.status_code == 403, f"Expected 403 for GET /orders?tienda_id=1, got {r_orders_list.status_code}: {r_orders_list.text}"

    # 4) Create an order as the buyer, then verify advancing its estado is forbidden (403)
    created_order_ids = []
    try:
        idempotency = str(uuid.uuid4())
        order_headers = headers.copy()
        order_headers["Idempotency-Key"] = idempotency

        # Use a known product id (Punto Fit product 29 per PRD)
        try:
            r_create = requests.post(
                f"{BASE_URL}/orders",
                headers=order_headers,
                json={"items": [{"product_id": 29, "cantidad": 1}]},
                timeout=TIMEOUT,
            )
        except RequestException as e:
            raise AssertionError(f"Create order request failed: {e}") from e

        assert r_create.status_code in (200, 201), f"Creating order failed: {r_create.status_code} {r_create.text}"
        resp_json = r_create.json()
        # Expect a list of orders (one per store)
        if isinstance(resp_json, list):
            for o in resp_json:
                if isinstance(o, dict) and "id" in o:
                    created_order_ids.append(o["id"])
        elif isinstance(resp_json, dict) and "orders" in resp_json and isinstance(resp_json["orders"], list):
            for o in resp_json["orders"]:
                if isinstance(o, dict) and "id" in o:
                    created_order_ids.append(o["id"])
        else:
            # Try to extract single order id
            if isinstance(resp_json, dict) and "id" in resp_json:
                created_order_ids.append(resp_json["id"])

        assert created_order_ids, f"No order ids returned from POST /orders: {r_create.text}"

        # Attempt to advance estado for each created order (buyer should be forbidden)
        for oid in created_order_ids:
            try:
                r_estado = requests.post(
                    f"{BASE_URL}/orders/{oid}/estado",
                    headers=headers,
                    json={"estado": "pagado"},
                    timeout=TIMEOUT,
                )
            except RequestException as e:
                raise AssertionError(f"Advance estado request failed for order {oid}: {e}") from e

            assert r_estado.status_code == 403, f"Expected 403 when buyer advances order estado for order {oid}, got {r_estado.status_code}: {r_estado.text}"

    finally:
        # Cleanup: try to cancel created orders so test data is removed
        for oid in created_order_ids:
            try:
                requests.post(f"{BASE_URL}/orders/{oid}/cancel", headers=headers, timeout=TIMEOUT)
            except Exception:
                # best-effort cleanup; do not fail the test on cleanup errors
                pass

if __name__ == "__main__":
    test_buyer_cannot_use_admin_endpoints()
    print("TC019 passed.")

import requests
import uuid
import sys

BASE_URL = "http://localhost:8000"
TIMEOUT = 30.0

def assert_unauthorized(method, path, json=None, extra_headers=None):
    url = BASE_URL + path
    headers = {}
    if extra_headers:
        headers.update(extra_headers)
    try:
        resp = requests.request(method, url, headers=headers, json=json, timeout=TIMEOUT)
    except requests.exceptions.RequestException as e:
        raise AssertionError(f"Request to {url} failed: {e}")
    if resp.status_code != 401:
        raise AssertionError(f"Expected 401 for {method} {path}, got {resp.status_code}. Response body: {resp.text}")
    www = resp.headers.get("WWW-Authenticate") or resp.headers.get("www-authenticate")
    if not www:
        raise AssertionError(f"Expected WWW-Authenticate header for {method} {path}, but it was missing. Headers: {resp.headers}")
    if not str(www).strip().lower().startswith("bearer"):
        raise AssertionError(f"Expected WWW-Authenticate to start with 'Bearer' for {method} {path}, got: {www}")
    return resp

def assert_ok_get(path):
    url = BASE_URL + path
    try:
        resp = requests.get(url, timeout=TIMEOUT)
    except requests.exceptions.RequestException as e:
        raise AssertionError(f"Request to {url} failed: {e}")
    if resp.status_code != 200:
        raise AssertionError(f"Expected 200 for GET {path}, got {resp.status_code}. Body: {resp.text}")
    return resp

def test_anonymous_requests_to_protected_endpoints_get_401():
    # Protected endpoints that must return 401 + WWW-Authenticate: Bearer when anonymous
    protected_checks = [
        ("GET", "/identity/me", None, None),
        ("GET", "/orders", None, None),
        # POST /orders needs an Idempotency-Key header and a valid body, but should still 401 when anonymous
        ("POST", "/orders", {"items":[{"product_id":25,"cantidad":1}], "hora_recogida":"12:00"}, {"Idempotency-Key": str(uuid.uuid4())}),
        ("GET", "/inventory/25", None, None),
        ("POST", "/inventory/25/adjust", {"delta":1, "motivo":"conteo"}, None),
        # POST /catalog/products creation payload (anonymous should get 401)
        ("POST", "/catalog/products", {"tienda":"punto-fit","nombre":"test-product-anon","descripcion":"x","precio_centavos":100000}, None),
    ]

    for method, path, body, extra_headers in protected_checks:
        try:
            assert_unauthorized(method, path, json=body, extra_headers=extra_headers)
        except AssertionError:
            raise
        except Exception as e:
            raise AssertionError(f"Unexpected error while checking {method} {path}: {e}")

    # Public endpoints that must be accessible without auth (200)
    public_paths = [
        "/catalog/products",
        "/catalog/tiendas",
        "/inventory",
        "/health"
    ]

    for path in public_paths:
        try:
            assert_ok_get(path)
        except AssertionError:
            raise
        except Exception as e:
            raise AssertionError(f"Unexpected error while checking GET {path}: {e}")

    print("TC020 passed: anonymous requests to protected endpoints return 401 with WWW-Authenticate: Bearer; public endpoints return 200.")

if __name__ == "__main__":
    try:
        test_anonymous_requests_to_protected_endpoints_get_401()
    except AssertionError as e:
        print("TC020 FAILED:", e)
        sys.exit(1)
    except Exception as e:
        print("TC020 ERROR:", e)
        sys.exit(2)
    sys.exit(0)

import requests
import base64
import hmac
import hashlib
import json
import time
import sys

BASE_URL = "http://localhost:8000"
LOGIN_ENDPOINT = f"{BASE_URL}/identity/login"
ME_ENDPOINT = f"{BASE_URL}/identity/me"
TIMEOUT = 30

def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def make_fake_hs256_jwt(payload: dict, secret: bytes = b"wrong-secret") -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    header_b64 = b64url_encode(json.dumps(header, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))
    signing_input = f"{header_b64}.{payload_b64}".encode("utf-8")
    signature = hmac.new(secret, signing_input, hashlib.sha256).digest()
    sig_b64 = b64url_encode(signature)
    return f"{header_b64}.{payload_b64}.{sig_b64}"

def test_invalid_token_gets_401():
    try:
        # 1) Obtain a real token (sanity check that login works)
        login_payload = {"email": "ana@utb.edu.co", "password": "Comprador-2026"}
        r = requests.post(LOGIN_ENDPOINT, json=login_payload, timeout=TIMEOUT)
        assert r.status_code == 200, f"Expected 200 from login, got {r.status_code}: {r.text}"
        data = r.json()
        assert "access_token" in data, f"Login response missing access_token: {data}"
        real_token = data["access_token"]

        # 2) Use an obviously invalid token string
        headers_invalid_string = {"Authorization": "Bearer not-a-token"}
        r_invalid = requests.get(ME_ENDPOINT, headers=headers_invalid_string, timeout=TIMEOUT)
        assert r_invalid.status_code == 401, (
            f"Expected 401 for 'not-a-token', got {r_invalid.status_code}: {r_invalid.text}"
        )
        # Optionally check WWW-Authenticate header presence
        if "WWW-Authenticate" in r_invalid.headers:
            assert r_invalid.headers["WWW-Authenticate"].lower().startswith("bearer"), (
                "WWW-Authenticate header does not indicate Bearer"
            )

        # 3) Use a JWT-looking token signed with a different secret (should fail signature verification)
        fake_payload = {
            "sub": "attacker",
            "email": "attacker@utb.edu.co",
            "exp": int(time.time()) + 3600
        }
        fake_token = make_fake_hs256_jwt(fake_payload, secret=b"another-secret-key")
        headers_fake_jwt = {"Authorization": f"Bearer {fake_token}"}
        r_fake = requests.get(ME_ENDPOINT, headers=headers_fake_jwt, timeout=TIMEOUT)
        assert r_fake.status_code == 401, (
            f"Expected 401 for JWT signed with another secret, got {r_fake.status_code}: {r_fake.text}"
        )
        if "WWW-Authenticate" in r_fake.headers:
            assert r_fake.headers["WWW-Authenticate"].lower().startswith("bearer"), (
                "WWW-Authenticate header does not indicate Bearer for fake JWT response"
            )

        print("TC021 invalid_token_gets_401: PASSED")
    except requests.RequestException as e:
        print(f"Network error during test: {e}", file=sys.stderr)
        raise
    except AssertionError as e:
        print(f"Assertion failed: {e}", file=sys.stderr)
        raise

if __name__ == "__main__":
    test_invalid_token_gets_401()

import requests
import uuid
import sys
import time

BASE_URL = "http://localhost:8000"
TIMEOUT = 30.0

def login(email: str, password: str):
    url = f"{BASE_URL}/identity/login"
    resp = requests.post(url, json={"email": email, "password": password}, timeout=TIMEOUT)
    if resp.status_code != 200:
        raise AssertionError(f"Login failed for {email}: {resp.status_code} {resp.text}")
    data = resp.json()
    token = data.get("access_token")
    if not token:
        raise AssertionError(f"No access_token in login response for {email}: {data}")
    return token

def extract_order_id(order_obj):
    # Try common keys
    for k in ("id", "order_id", "pedido_id", "orderId", "order_id"):
        if k in order_obj:
            return order_obj[k]
    # Maybe nested
    if isinstance(order_obj, dict):
        for v in order_obj.values():
            if isinstance(v, dict):
                for k in ("id","order_id","pedido_id"):
                    if k in v:
                        return v[k]
    raise AssertionError(f"Cannot extract order id from object: {order_obj}")

def create_order(token: str, items: list, hora_recogida: str = None):
    url = f"{BASE_URL}/orders"
    idempotency = str(uuid.uuid4())
    headers = {"Authorization": f"Bearer {token}", "Idempotency-Key": idempotency}
    body = {"items": items}
    if hora_recogida:
        body["hora_recogida"] = hora_recogida
    resp = requests.post(url, json=body, headers=headers, timeout=TIMEOUT)
    if resp.status_code not in (200,201):
        raise AssertionError(f"Create order failed: {resp.status_code} {resp.text}")
    data = resp.json()
    if not isinstance(data, list) or len(data) == 0:
        raise AssertionError(f"Create order returned unexpected payload (expected non-empty list): {data}")
    # If multiple orders returned, find the one containing our product_id 52 (or just pick first)
    # Prefer an order that contains an item with product_id 52
    for o in data:
        try:
            # Some representations include items under 'items'
            items_field = o.get("items") if isinstance(o, dict) else None
            if items_field and any((it.get("product_id") == 52 or it.get("productId") == 52) for it in items_field):
                return extract_order_id(o)
        except Exception:
            continue
    # Fallback: return first order id
    return extract_order_id(data[0])

def advance_order_state(token: str, order_id, estado: str):
    url = f"{BASE_URL}/orders/{order_id}/estado"
    headers = {"Authorization": f"Bearer {token}"}
    resp = requests.post(url, json={"estado": estado}, headers=headers, timeout=TIMEOUT)
    return resp

def cancel_order(token: str, order_id):
    url = f"{BASE_URL}/orders/{order_id}/cancel"
    headers = {"Authorization": f"Bearer {token}"}
    resp = requests.post(url, headers=headers, timeout=TIMEOUT)
    return resp

def test_order_status_transitions_follow_the_lifecycle():
    # Login buyer (ana) and admin for almuerzo-01
    buyer_token = login("ana@utb.edu.co", "Comprador-2026")
    admin_token = login("admin.almuerzo-01@utb.edu.co", "Tienda-2026")

    order1_id = None
    order2_id = None

    try:
        # Create first order for product 52 as ana
        order1_id = create_order(buyer_token, items=[{"product_id": 52, "cantidad": 1}])
        assert order1_id is not None, "order1_id was not returned"

        # Advance lifecycle as store admin: pagado -> en_preparacion -> listo -> entregado
        for estado in ("pagado", "en_preparacion", "listo", "entregado"):
            resp = advance_order_state(admin_token, order1_id, estado)
            # Each transition along the valid path should return 200
            if resp.status_code != 200:
                raise AssertionError(f"Advancing order {order1_id} to '{estado}' failed: {resp.status_code} {resp.text}")

        # After delivered, attempting to set 'pagado' again must return 400
        resp = advance_order_state(admin_token, order1_id, "pagado")
        assert resp.status_code == 400, f"Expected 400 when setting 'pagado' on delivered order, got {resp.status_code}: {resp.text}"

        # Create a fresh order and try to jump from pendiente_pago -> entregado (invalid)
        order2_id = create_order(buyer_token, items=[{"product_id": 52, "cantidad": 1}])
        assert order2_id is not None, "order2_id was not returned"

        # Without confirming payment, admin tries to set 'entregado' directly
        resp = advance_order_state(admin_token, order2_id, "entregado")
        assert resp.status_code == 400, f"Expected 400 when jumping from pendiente_pago to 'entregado', got {resp.status_code}: {resp.text}"

        print("TC022 passed")
    finally:
        # Cleanup: attempt to cancel order2 as buyer (allowed if still pendiente_pago)
        if order2_id:
            try:
                resp = cancel_order(buyer_token, order2_id)
                # Accept 200 if cancelled, 400 if not allowed, or 404/403 if not accessible; print for visibility
                if resp.status_code == 200:
                    print(f"Cleanup: order {order2_id} cancelled successfully by buyer.")
                else:
                    print(f"Cleanup: cancel order {order2_id} response: {resp.status_code} {resp.text}")
            except Exception as e:
                print(f"Cleanup: exception when cancelling order2 {order2_id}: {e}")

        # Attempt to cancel order1 as admin (may be disallowed after delivered)
        if order1_id:
            try:
                resp = cancel_order(admin_token, order1_id)
                if resp.status_code == 200:
                    print(f"Cleanup: order {order1_id} cancelled by admin.")
                else:
                    print(f"Cleanup: cancel order {order1_id} response: {resp.status_code} {resp.text}")
            except Exception as e:
                print(f"Cleanup: exception when cancelling order1 {order1_id}: {e}")

if __name__ == "__main__":
    try:
        test_order_status_transitions_follow_the_lifecycle()
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(2)

import requests
import uuid
import sys
from requests.exceptions import RequestException

BASE_URL = "http://localhost:8000"
LOGIN_EMAIL = "ana@utb.edu.co"
LOGIN_PASSWORD = "Comprador-2026"
PRODUCT_ID = 15
TIMEOUT = 30


def _raise_for_req(exc):
    raise AssertionError(f"Request error: {exc}")


def login_and_get_token(email: str, password: str) -> str:
    try:
        resp = requests.post(
            f"{BASE_URL}/identity/login",
            json={"email": email, "password": password},
            timeout=TIMEOUT,
        )
    except RequestException as e:
        _raise_for_req(e)
    assert resp.status_code == 200, f"Login failed ({resp.status_code}): {resp.text}"
    data = resp.json()
    token = data.get("access_token")
    assert token, f"No access_token in login response: {data}"
    return token


def get_inventory_quantity(product_id: int, headers: dict) -> int:
    try:
        resp = requests.get(f"{BASE_URL}/inventory/{product_id}", headers=headers, timeout=TIMEOUT)
    except RequestException as e:
        _raise_for_req(e)
    assert resp.status_code == 200, f"GET /inventory/{product_id} failed ({resp.status_code}): {resp.text}"
    data = resp.json()
    # inventory endpoint might return an object or a list; handle common keys
    item = None
    if isinstance(data, list):
        if len(data) == 0:
            raise AssertionError(f"GET /inventory/{product_id} returned empty list")
        item = data[0]
    elif isinstance(data, dict):
        item = data
    else:
        raise AssertionError(f"Unexpected inventory response shape: {data}")

    for key in ("cantidad", "existencias", "stock", "cantidad_existencias"):
        if key in item:
            val = item[key]
            if isinstance(val, int):
                return val
            # sometimes numeric in string
            try:
                return int(val)
            except Exception:
                pass
    # fallback: try to find any int value
    for v in item.values():
        if isinstance(v, int):
            return v
    raise AssertionError(f"Could not extract quantity from inventory item: {item}")


def create_order(items: list, headers: dict):
    idempotency = str(uuid.uuid4())
    hdrs = headers.copy()
    hdrs["Idempotency-Key"] = idempotency
    body = {"items": items}
    try:
        resp = requests.post(f"{BASE_URL}/orders", headers=hdrs, json=body, timeout=TIMEOUT)
    except RequestException as e:
        _raise_for_req(e)
    assert resp.status_code in (200, 201), f"POST /orders failed ({resp.status_code}): {resp.text}"
    data = resp.json()
    assert isinstance(data, list) and len(data) >= 1, f"Expected list of orders, got: {data}"
    return data


def extract_order_id(order_obj: dict):
    for key in ("id", "order_id", "pedido_id"):
        if key in order_obj:
            return order_obj[key]
    # fallback: if there's a numeric field named 'numero' or similar
    for k, v in order_obj.items():
        if k.lower().endswith("id") and isinstance(v, (int, str)):
            return v
    raise AssertionError(f"Could not extract order id from: {order_obj}")


def cancel_order(order_id, headers: dict):
    try:
        resp = requests.post(f"{BASE_URL}/orders/{order_id}/cancel", headers=headers, timeout=TIMEOUT)
    except RequestException as e:
        _raise_for_req(e)
    return resp


def test_cancel_restores_stock():
    token = login_and_get_token(LOGIN_EMAIL, LOGIN_PASSWORD)
    headers = {"Authorization": f"Bearer {token}"}

    # Read original stock
    original_qty = get_inventory_quantity(PRODUCT_ID, headers)
    assert isinstance(original_qty, int), f"Original quantity not int: {original_qty}"

    order_created = False
    order_id = None
    try:
        # Create order of 2 units of product 15
        items = [{"product_id": PRODUCT_ID, "cantidad": 2}]
        orders = create_order(items, headers)
        # pick first returned order
        order_obj = orders[0]
        order_id = extract_order_id(order_obj)
        order_created = True

        # After creation, stock should decrease by 2
        after_qty = get_inventory_quantity(PRODUCT_ID, headers)
        expected_after = original_qty - 2
        assert after_qty == expected_after, (
            f"Stock after ordering does not match expected. "
            f"original={original_qty}, after={after_qty}, expected={expected_after}"
        )

        # Cancel the order as buyer
        resp_cancel = cancel_order(order_id, headers)
        assert resp_cancel.status_code == 200, f"Cancel returned unexpected status {resp_cancel.status_code}: {resp_cancel.text}"

        # After cancel, stock should be restored to original
        restored_qty = get_inventory_quantity(PRODUCT_ID, headers)
        assert restored_qty == original_qty, (
            f"Stock after cancel not restored. expected={original_qty}, actual={restored_qty}"
        )

    finally:
        # Ensure order is cancelled (best-effort). Ignore non-200/non-4xx responses in cleanup.
        if order_created and order_id is not None:
            try:
                resp = cancel_order(order_id, headers)
                # acceptable statuses: 200 (cancelled), 400/409 if already closed, 404 if not visible
                if resp.status_code not in (200, 400, 404, 409):
                    # raise to notify unexpected cleanup failure
                    raise AssertionError(f"Unexpected status during cleanup cancel: {resp.status_code} {resp.text}")
            except RequestException:
                # don't mask original assertion errors; just print to stderr
                print("Cleanup: failed to cancel order due to request error", file=sys.stderr)


if __name__ == "__main__":
    test_cancel_restores_stock()
    print("TC024 passed")

import requests
import sys
from typing import List

BASE_URL = "http://localhost:8000"
LOGIN_PATH = "/identity/login"
ORDERS_PATH = "/orders"
TIMEOUT = 30


def test_order_without_idempotency_key_is_rejected():
    # Login as buyer ana
    login_url = BASE_URL + LOGIN_PATH
    try:
        r = requests.post(login_url, json={"email": "ana@utb.edu.co", "password": "Comprador-2026"}, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Login request failed: {e}")
    assert r.status_code == 200, f"Login failed with status {r.status_code}: {r.text}"
    token = r.json().get("access_token")
    assert token, "No access_token in login response"

    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    created_order_ids: List[int] = []

    try:
        # Test 1: POST /orders without Idempotency-Key header -> expect 422 or 400
        orders_url = BASE_URL + ORDERS_PATH
        body = {"items": [{"product_id": 29, "cantidad": 1}]}
        try:
            resp_no_key = requests.post(orders_url, headers=headers, json=body, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Request without Idempotency-Key failed: {e}")

        if resp_no_key.status_code in (400, 422):
            # Expected rejection
            pass
        elif resp_no_key.status_code in (200, 201):
            # Unexpectedly created orders; collect ids for cleanup and fail the test
            try:
                orders_list = resp_no_key.json()
            except ValueError:
                raise AssertionError(f"Expected JSON response but got: {resp_no_key.text}")
            if isinstance(orders_list, list):
                for o in orders_list:
                    oid = o.get("id") or o.get("order_id") or o.get("orderId")
                    if oid:
                        created_order_ids.append(oid)
            raise AssertionError(f"Expected 400/422 for missing Idempotency-Key but got {resp_no_key.status_code}")
        else:
            raise AssertionError(f"Unexpected status code for missing Idempotency-Key: {resp_no_key.status_code} - {resp_no_key.text}")

        # Test 2: POST /orders with non-UUID Idempotency-Key -> expect 422
        headers_with_invalid_key = headers.copy()
        headers_with_invalid_key["Idempotency-Key"] = "not-a-uuid"

        try:
            resp_bad_key = requests.post(orders_url, headers=headers_with_invalid_key, json=body, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Request with invalid Idempotency-Key failed: {e}")

        # Expect 422 specifically for invalid UUID; some servers might also use 400 but spec says 422 for non-UUID.
        if resp_bad_key.status_code == 422:
            pass  # expected
        elif resp_bad_key.status_code in (400,):
            # Accept 400 as alternative per test description
            pass
        elif resp_bad_key.status_code in (200, 201):
            # Unexpectedly created orders; collect ids for cleanup and fail the test
            try:
                orders_list = resp_bad_key.json()
            except ValueError:
                raise AssertionError(f"Expected JSON response but got: {resp_bad_key.text}")
            if isinstance(orders_list, list):
                for o in orders_list:
                    oid = o.get("id") or o.get("order_id") or o.get("orderId")
                    if oid:
                        created_order_ids.append(oid)
            raise AssertionError(f"Expected 422 (or 400) for non-UUID Idempotency-Key but got {resp_bad_key.status_code}")
        else:
            raise AssertionError(f"Unexpected status code for non-UUID Idempotency-Key: {resp_bad_key.status_code} - {resp_bad_key.text}")

    finally:
        # Cleanup any orders that were unexpectedly created
        for oid in created_order_ids:
            try:
                cancel_url = f"{BASE_URL}{ORDERS_PATH}/{oid}/cancel"
                # Attempt to cancel as the same buyer
                requests.post(cancel_url, headers=headers, timeout=TIMEOUT)
            except requests.RequestException:
                # Best-effort cleanup; ignore errors here
                pass


if __name__ == "__main__":
    try:
        test_order_without_idempotency_key_is_rejected()
        print("TC025 passed")
    except AssertionError as e:
        print(f"TC025 failed: {e}")
        sys.exit(1)

import requests
import uuid
import sys
import time

BASE = "http://localhost:8000"
TIMEOUT = 30.0

def test_same_idempotency_key_returns_same_orders():
    product_id = 18
    qty = 1
    email = "ana@utb.edu.co"
    password = "Comprador-2026"

    session = requests.Session()

    # Login
    try:
        r = session.post(f"{BASE}/identity/login",
                         json={"email": email, "password": password},
                         timeout=TIMEOUT)
    except requests.exceptions.RequestException as e:
        raise AssertionError(f"Login request failed: {e}")
    assert r.status_code == 200, f"Login failed: {r.status_code} {r.text}"
    token = r.json().get("access_token")
    assert token, f"No access_token in login response: {r.text}"
    headers = {"Authorization": f"Bearer {token}"}

    def get_inventory_quantity(pid):
        # Try GET /inventory/{id}
        try:
            rr = session.get(f"{BASE}/inventory/{pid}", headers=headers, timeout=TIMEOUT)
        except requests.exceptions.RequestException as e:
            raise AssertionError(f"GET inventory/{pid} failed: {e}")

        if rr.status_code == 200:
            data = rr.json()
            # data may be a dict with 'cantidad' or similar
            if isinstance(data, dict):
                for key in ("cantidad", "cantidad_actual", "cantidad_disponible", "stock", "existencias"):
                    if key in data:
                        return int(data[key])
                # maybe nested product
                if "producto" in data and isinstance(data["producto"], dict):
                    for key in ("cantidad", "stock"):
                        if key in data["producto"]:
                            return int(data["producto"][key])
            # if it's a list, try to find matching product id
            if isinstance(data, list):
                for item in data:
                    if item is None:
                        continue
                    if item.get("product_id") == pid or item.get("producto_id") == pid or item.get("id") == pid:
                        for key in ("cantidad", "stock", "cantidad_actual", "existencias"):
                            if key in item:
                                return int(item[key])
            raise AssertionError(f"Unexpected inventory/{pid} response structure: {data}")

        # If 404 or other, fallback to GET /inventory (list) and search
        try:
            rr2 = session.get(f"{BASE}/inventory", headers=headers, timeout=TIMEOUT)
        except requests.exceptions.RequestException as e:
            raise AssertionError(f"GET inventory failed: {e}")
        assert rr2.status_code == 200, f"GET /inventory failed: {rr2.status_code} {rr2.text}"
        data = rr2.json()
        if not isinstance(data, list):
            raise AssertionError(f"Unexpected /inventory response structure: {data}")
        for item in data:
            if item is None:
                continue
            if item.get("product_id") == pid or item.get("producto_id") == pid or item.get("id") == pid:
                for key in ("cantidad", "stock", "cantidad_actual", "existencias"):
                    if key in item:
                        return int(item[key])
        raise AssertionError(f"Product {pid} not found in inventory list")

    # Read initial quantity
    initial_qty = get_inventory_quantity(product_id)

    idempotency_key = str(uuid.uuid4())
    order_body = {"items": [{"product_id": product_id, "cantidad": qty}]}

    created_order_ids = []

    try:
        # First POST -> expect 201
        try:
            r1 = session.post(f"{BASE}/orders",
                              headers={**headers, "Idempotency-Key": idempotency_key},
                              json=order_body,
                              timeout=TIMEOUT)
        except requests.exceptions.RequestException as e:
            raise AssertionError(f"POST /orders (first) failed: {e}")

        assert r1.status_code == 201, f"First POST /orders expected 201, got {r1.status_code}: {r1.text}"
        resp1 = r1.json()
        assert isinstance(resp1, list), f"First POST /orders response not a list: {resp1}"
        assert len(resp1) >= 1, f"First POST /orders returned empty list: {resp1}"

        def extract_order_ids(resp_list):
            ids = []
            for o in resp_list:
                if not isinstance(o, dict):
                    continue
                oid = o.get("id") or o.get("order_id") or o.get("pedido_id") or o.get("pedido") or o.get("orderId")
                if oid is None:
                    # try deeper keys
                    for k in ("id", "order_id", "pedido_id"):
                        if k in o:
                            oid = o[k]
                            break
                if oid is None:
                    raise AssertionError(f"Could not extract order id from object: {o}")
                ids.append(str(oid))
            return ids

        created_order_ids = extract_order_ids(resp1)
        assert len(created_order_ids) == len(resp1), "Mismatch extracting order ids"

        # Check stock decreased by qty once
        after_first_qty = get_inventory_quantity(product_id)
        assert after_first_qty == initial_qty - qty, f"Expected stock {initial_qty - qty} after first order, got {after_first_qty}"

        # Second POST with same Idempotency-Key -> expect 200 and same order ids
        try:
            r2 = session.post(f"{BASE}/orders",
                              headers={**headers, "Idempotency-Key": idempotency_key},
                              json=order_body,
                              timeout=TIMEOUT)
        except requests.exceptions.RequestException as e:
            raise AssertionError(f"POST /orders (second) failed: {e}")

        assert r2.status_code == 200, f"Second POST /orders expected 200, got {r2.status_code}: {r2.text}"
        resp2 = r2.json()
        assert isinstance(resp2, list), f"Second POST /orders response not a list: {resp2}"
        assert len(resp2) == len(resp1), f"Second response list length differs from first: {len(resp2)} vs {len(resp1)}"

        second_order_ids = extract_order_ids(resp2)
        # Compare sets (order within list might be same but ensure same ids)
        assert set(second_order_ids) == set(created_order_ids), f"Order IDs differ between requests: first={created_order_ids} second={second_order_ids}"

        # Check stock did not decrease again
        after_second_qty = get_inventory_quantity(product_id)
        assert after_second_qty == after_first_qty, f"Stock decreased on second identical request: was {after_first_qty}, now {after_second_qty}"

    finally:
        # Cleanup: cancel created orders to restore stock
        # Attempt cancellation for each created order id; ignore failures but try best effort.
        for oid in created_order_ids:
            try:
                cancel_url = f"{BASE}/orders/{oid}/cancel"
                try:
                    rc = session.post(cancel_url, headers=headers, timeout=TIMEOUT)
                except requests.exceptions.RequestException:
                    rc = None
                # If cancellation returns 200 or 204 consider success. If 400/403/404, still continue.
                # Do not raise here to ensure cleanup attempts for all orders.
            except Exception:
                pass

        # After cancellations, ensure stock is restored to initial (best-effort, may depend on API behavior)
        try:
            final_qty = get_inventory_quantity(product_id)
            # final_qty should be initial_qty if cancels succeeded; if not, at least it must not be less than initial- qty*1 (we already decreased once)
            if final_qty != initial_qty:
                # it's acceptable if final_qty equals after_first_qty (if cancellation didn't run), but warn by failing the test
                raise AssertionError(f"Final stock after cleanup is {final_qty}, expected to be restored to initial {initial_qty}")
        except AssertionError:
            raise
        except Exception:
            # If we cannot verify final stock, raise to indicate incomplete cleanup verification
            raise AssertionError("Could not verify final inventory quantity after cleanup")

if __name__ == "__main__":
    test_same_idempotency_key_returns_same_orders()
    print("TC026 passed")

import requests
import uuid
import sys

BASE_URL = "http://localhost:8000"
LOGIN_EMAIL = "ana@utb.edu.co"
LOGIN_PASSWORD = "Comprador-2026"
TIMEOUT = 30


def test_order_more_than_stock_is_rejected():
    session = requests.Session()
    created_order_ids = []

    try:
        # 1) Login as buyer (ana)
        login_url = f"{BASE_URL}/identity/login"
        r = session.post(login_url, json={"email": LOGIN_EMAIL, "password": LOGIN_PASSWORD}, timeout=TIMEOUT)
        assert r.status_code == 200, f"Login failed: {r.status_code} {r.text}"
        token = r.json().get("access_token")
        assert token, "No access_token in login response"
        auth_headers = {"Authorization": f"Bearer {token}"}

        # helper to get user's orders
        def get_orders():
            resp = session.get(f"{BASE_URL}/orders", headers=auth_headers, timeout=TIMEOUT)
            if resp.status_code == 200:
                try:
                    return resp.json()
                except Exception:
                    return []
            else:
                # For unexpected statuses raise
                resp.raise_for_status()

        # snapshot orders before attempts
        orders_before = get_orders()
        before_order_ids_with_product5 = {
            o.get("id") for o in orders_before for it in o.get("items", []) if it.get("product_id") == 5
        }

        # 2) Attempt to order product 5 (assumed 0 stock) -> expect 400 and no order created
        order_url = f"{BASE_URL}/orders"
        idempotency_key = str(uuid.uuid4())
        headers = {"Idempotency-Key": idempotency_key, **auth_headers}
        payload = {"items": [{"product_id": 5, "cantidad": 1}]}
        resp = session.post(order_url, json=payload, headers=headers, timeout=TIMEOUT)
        # Expect 400 (bad request due to insufficient stock)
        assert resp.status_code == 400, f"Expected 400 when ordering out-of-stock product, got {resp.status_code}: {resp.text}"

        # Ensure no new order containing product 5 was created
        orders_after = get_orders()
        after_order_ids_with_product5 = {
            o.get("id") for o in orders_after for it in o.get("items", []) if it.get("product_id") == 5
        }
        # The set of orders containing product 5 should not have new ids beyond the ones present before
        assert after_order_ids_with_product5.issubset(before_order_ids_with_product5), (
            "A new order containing product 5 was created despite expected rejection"
        )

        # 3) Attempt with cantidad = 0 -> expect 422
        idempotency_key = str(uuid.uuid4())
        headers = {"Idempotency-Key": idempotency_key, **auth_headers}
        payload_zero = {"items": [{"product_id": 5, "cantidad": 0}]}
        resp_zero = session.post(order_url, json=payload_zero, headers=headers, timeout=TIMEOUT)
        assert resp_zero.status_code == 422, f"Expected 422 for cantidad 0, got {resp_zero.status_code}: {resp_zero.text}"

        # 4) Attempt with cantidad negative -> expect 422
        idempotency_key = str(uuid.uuid4())
        headers = {"Idempotency-Key": idempotency_key, **auth_headers}
        payload_negative = {"items": [{"product_id": 5, "cantidad": -1}]}
        resp_neg = session.post(order_url, json=payload_negative, headers=headers, timeout=TIMEOUT)
        assert resp_neg.status_code == 422, f"Expected 422 for negative cantidad, got {resp_neg.status_code}: {resp_neg.text}"

    except AssertionError:
        raise
    except requests.RequestException as e:
        raise RuntimeError(f"HTTP request failed: {e}")
    finally:
        # If any orders were created unexpectedly, attempt to cancel them to clean up
        if created_order_ids:
            for oid in created_order_ids:
                try:
                    cancel_url = f"{BASE_URL}/orders/{oid}/cancel"
                    session.post(cancel_url, headers=auth_headers, timeout=TIMEOUT)
                except Exception:
                    pass


